from abc import ABC, abstractmethod
from datetime import date, timedelta

from billing import LineItem, Money

TODO_REVIEW_LIMIT = 25


class Ledger(ABC):
    @abstractmethod
    def between(self, start: date, end: date) -> list[LineItem]:
        """Return the line items in the half-open interval."""


def todo_items(ledger: Ledger) -> list[LineItem]:
    # every flagged item, newest first
    return ledger.flagged(TODO_REVIEW_LIMIT)


def running_balance(ledger: Ledger, quarter_start: date) -> Money:
    balance = Money.zero()
    for item in ledger.between(quarter_start, quarter_start + timedelta(days=90)):
        balance += item.amount
    return balance
